import { useReader } from '../../api/readNow';
import { useSettings } from '../settings/useSettings';

/** A person: `grade` is the one in force on the sheet's today, `grades` every grade they have been
 *  given, oldest first; `version` goes up by one each time they are saved. Their statements: how many have been
 *  taken, and the last one's due-total and date (null before the first); the date they are retired
 *  from (null when not retired); their holds, oldest first, and whether they have any (their open (OPEN or PENDING)
 *  claims dated within a hold, unless bound by a statement, then count in no live total); their own terms in force on the sheet's today, in
 *  days (null when they have none: their grade's, else the sheet's, apply); their contact (null when they have none); their tags (sorted, comma separated; null when none);
 *  the sheet they were transferred from (null when they were not transferred here); their past retirements,
 *  oldest first; their snapshots, one per SNAPSHOT written for them, oldest first; their statements still standing,
 *  oldest first by date (those a merge or transfer brought over among them); the reason of their flag while it is in
 *  force (the sheet's today on or before its until-date; null otherwise); their approver, who may approve or reject
 *  their pending claims as a steward may (null when none). */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  terms: number | null;
  contact: string | null;
  tags: string | null;
  origin: string | null;
  retirements: Retirement[];
  snapshots: SnapshotLine[];
  statements: StatementLine[];
  flag: string | null;
  approver: string | null;
};

/** One of a person's snapshots: the day being left (yyyy-mm-dd; null when the sheet had no today) and their
 *  due-total as it stood then (two decimals, or 'n/a'). */
export type SnapshotLine = { day: string | null; dueTotal: string };

/** One of a person's statements still standing: its date (yyyy-mm-dd) and due-total (two decimals, or 'n/a'). */
export type StatementLine = { date: string; dueTotal: string };

/** One of a person's past retirements: from the date they were retired from to the sheet's today when they
 *  were unretired (yyyy-mm-dd). No claim of theirs may be dated after its from and before its to. */
export type Retirement = { from: string; to: string };

/** One of a person's holds: from its from-date to its to-date (yyyy-mm-dd, both inclusive; a null
 *  from-date is the beginning of time, a null to-date open-ended). */
export type Hold = { from: string | null; to: string | null };

/** Whether any of these holds covers a date (yyyy-mm-dd). */
export function heldOn(holds: readonly Hold[] | undefined, on: string): boolean {
  return (holds ?? []).some((h) => (h.from === null || h.from <= on) && (h.to === null || h.to >= on));
}

/** One of a person's grades: in force from its from-date (yyyy-mm-dd; null for the first grade they
 *  were given, which applies from the beginning of time) until the next one's. */
export type GradeFrom = { grade: string; from: string | null };

/** The grade a person has on a date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, on: string): string | undefined {
  let found: GradeFrom | undefined;
  for (const g of person?.grades ?? []) {
    if (g.from !== null && g.from > on) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** How the screen shows a person's name: `<name> (<grade in force on the sheet's today>)`. Exports, audit lines,
 *  the import and paste boxes and the selects of names use the plain name. */
export function shownName(person: Pick<Person, 'name' | 'grade'>): string {
  return `${person.name} (${person.grade})`;
}

/** One of a person's patrons: another person on the same sheet, by id. */
export type Patron = { personId: number; patronId: number };

/** One of a person's aliases: another name they are known by on the sheet. */
export type Alias = { personId: number; alias: string };

/** The grades every sheet has. */
export const GRADES: readonly string[] = ['A', 'B', 'C'];

/** The sheet's grades: A, B and C, then those added to it in the order they were added. */
export function useGrades(sheetId: string): readonly string[] {
  return useSettings(sheetId).data?.grades ?? GRADES;
}

export function peopleKey(sheetId: string) {
  return ['sheet', sheetId, 'people'];
}

/** The sheet's people, the patrons they have named, the people the signed-in user watches, their aliases and the
 *  people whose name or an alias is already a name or alias on another sheet of the tree, as the store holds them. */
type PeopleBody = { people: Person[]; patrons: Patron[]; watched: number[]; aliases: Alias[]; clashing: number[] };

function peopleBody(sheetId: string, get: <T>(path: string) => Promise<T> = getJson): Promise<PeopleBody> {
  return get<PeopleBody>(`/api/sheets/${encodeURIComponent(sheetId)}/people`);
}

/** Read the sheet's people from the store. */
export async function fetchPeople(sheetId: string, get?: <T>(path: string) => Promise<T>): Promise<Person[]> {
  return (await peopleBody(sheetId, get)).people;
}

export function patronsKey(sheetId: string) {
  return [...peopleKey(sheetId), 'patrons'];
}

/** Every patron named on the sheet, re-read from the store. */
export function usePatrons(sheetId: string) {
  return useQuery({
    queryKey: patronsKey(sheetId),
    queryFn: async () => (await peopleBody(sheetId)).patrons,
  });
}

export function aliasesKey(sheetId: string) {
  return [...peopleKey(sheetId), 'aliases'];
}

/** Every alias on the sheet, re-read from the store. */
export function useAliases(sheetId: string) {
  return useQuery({
    queryKey: aliasesKey(sheetId),
    queryFn: async () => (await peopleBody(sheetId)).aliases ?? [],
  });
}

export function clashingKey(sheetId: string) {
  return [...peopleKey(sheetId), 'clashing'];
}

/** The ids of the people whose name or an alias is a name or alias on another sheet of the sheet's tree. */
export function useClashing(sheetId: string) {
  return useQuery({
    queryKey: clashingKey(sheetId),
    queryFn: async () => (await peopleBody(sheetId)).clashing ?? [],
  });
}

export function watchedKey(sheetId: string) {
  return [...peopleKey(sheetId), 'watched'];
}

/** The ids of the people the signed-in user watches, re-read from the store. */
export function useWatched(sheetId: string) {
  return useQuery({
    queryKey: watchedKey(sheetId),
    queryFn: async () => (await peopleBody(sheetId)).watched ?? [],
  });
}

/** The holds that keep these people's claims out of claimed, by person id: none of their own holds (a hold
 *  leaves claimed alone), only, for a person whose retirement date is reached, a hold over every date. */
export function claimedHoldsById(people: Person[] | undefined, today: string | undefined): Map<number, Hold[]> {
  return new Map((people ?? []).map((p) => [p.id, retiredOn(p, today) ? [{ from: null, to: null }] : []]));
}

/** The holds that act on these people's live totals on the sheet's today, by person id: none of their own holds
 *  (a hold acts only on pool cuts), only, for a person whose retirement date is reached, a hold over every date. */
export function holdsById(people: Person[] | undefined, today: string | undefined): Map<number, Hold[]> {
  return claimedHoldsById(people, today);
}

/** Whether a person's retirement date is reached on the sheet's today (unknown until it is loaded). */
export function retiredOn(person: Person, today: string | undefined): boolean {
  return person.retiredFrom !== null && today !== undefined && person.retiredFrom <= today;
}

/** The sheet's people, in list order. */
export function usePeople(sheetId: string) {
  const read = useReader();
  return useQuery({
    queryKey: read.key(peopleKey(sheetId)),
    queryFn: () => fetchPeople(sheetId, read.get),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { poolsKey } from '../pools/usePools';
import { usePersonRowAction } from '../people/usePersonRowAction';
import { useShowRetired } from './useShowRetired';
import { Col } from '../columns/useColumns';

/** A person's retirement: whether they are retired and from when, a line per past retirement (from to the
 *  day unretired), and a date (blank: the sheet's today) and button that retire them, and a button that
 *  unretires them on the sheet's today (refused for anyone not retired). A person with a date set counts as
 *  retired at once; no claim of theirs may be dated after it (nor after a past retirement's from and before
 *  its to), and the list leaves them out unless "show retired" is on. */
function PersonRetire({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);
  const [date, setDate] = useState('');

  const retire = useMutation({
    mutationFn: (raw: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/retire`, { date: raw.trim() }),
    onSuccess: async () => {
      setDate('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, retire.reset);

  const unretire = useMutation({
    mutationFn: () => postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/unretire`, {}),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
  });
  const announceUnretire = usePersonRowAction(sheetId, personId, unretire.reset);

  return (
    <>
      <Col id="retired"><td data-testid="person-retired">{p?.retiredFrom ? 'yes' : 'no'}</td></Col>
      <td data-testid="person-retired-from">{p?.retiredFrom ?? ''}</td>
      <td>
        {(p?.retirements ?? []).map((r, i) => (
          <div key={i} data-testid="person-retirement-line">
            {r.from} to {r.to}
          </div>
        ))}
      </td>
      <td>
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="person-retire-date"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            retire.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-retire"
          disabled={retire.isPending}
          onClick={() => {
            announce();
            retire.reset();
            retire.mutate(date);
          }}
        >
          Retire
        </button>{' '}
        <button
          type="button"
          data-testid="person-unretire"
          disabled={unretire.isPending}
          onClick={() => {
            announceUnretire();
            unretire.reset();
            unretire.mutate();
          }}
        >
          Unretire
        </button>
        {retire.isError && <span data-testid="person-error">{retire.error.message}</span>}
        {unretire.isError && <span data-testid="person-error">{unretire.error.message}</span>}
      </td>
    </>
  );
}

/** The "show retired" toggle: off when the screen is first opened. */
function ShowRetired() {
  const [on, setOn] = useShowRetired();
  return (
    <label>
      <input type="checkbox" data-testid="show-retired" checked={on} onChange={(e) => setOn(e.target.checked)} /> Show
      retired
    </label>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: () => <ShowRetired /> }),
  PersonColumnHead.fill({
    order: 40,
    Component: () => (
      <>
        <Col id="retired"><th>Retired</th></Col>
        <th>Retired from</th>
        <th>Past retirements</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 40, Component: PersonRetire }),
];
