package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;

/** A claim's editor lock: opening the editor (the edit button) locks the claim for every other user until its
 *  editor is saved or cancelled, or the sheet's today changes. Only a DRAFT outside a closed period can be
 *  edited: any other claim is refused and takes no lock, as is a claim another user holds. A refusal writes nothing. */
final class ClaimLock {
    private ClaimLock() {
    }

    static Claim lock(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods)
            throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!found.status().equals("DRAFT")) {
            throw new BadRequestException("only a DRAFT claim can be edited");
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        if (!repository.lock(id, found, by)) {
            throw new BadRequestException("the claim is being edited by " + repository.lockedBy(id, cid));
        }
        return found;
    }

    static Claim unlock(String id, long cid, String by, ClaimRepository repository) throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        repository.unlock(id, cid, by);
        return found;
    }
}
      dueBy: a === 'due-by' ? (dueBys[id] ?? '').trim() : '',
    });
  };

  // Only a DRAFT outside a closed period (the one containing its due-by), not locked by another user, can be edited, and not by a viewer: editing
  // any other claim is refused on its row, opens no editor and takes no lock (to change an open claim, void it and
  // add a new one). What this screen already knows is refused at once; the server refuses the rest, and the editor
  // then goes back to what it was.
  const openEditor = (c: Claim) => {
    save.reset();
    action.reset();
    reassign.reset();
    inline.reset();
    lock.reset();
    const role = roleOf(settings, user, today);
    const known =
      sheet?.archived ? 'the sheet is archived'
      : role === 'viewer' ? 'a viewer can change nothing'
      : c.status !== 'DRAFT' ? 'only a DRAFT claim can be edited'
      : periodOf(periods.data, c.dueBy)?.closed ? `the period ${periodOf(periods.data, c.dueBy)?.name} is closed`
      : c.lockedBy !== null && c.lockedBy !== user ? `the claim is being edited by ${c.lockedBy}`
      : null;
    if (known !== null) {
      setRefused({ id: c.id, message: known });
      return;
    }
    setRefused(null);
    const before = { editing, amount, date, note, corrects, ref, tags };
    fillForm(c);
    lock.mutate(
      { id: c.id, action: 'lock' },
      {
        onError: (e) => {
          setRefused({ id: c.id, message: e.message });
          setEditing(before.editing);
          setAmount(before.amount);
          setDate(before.date);
          setNote(before.note);
          setCorrects(before.corrects);
          setRef(before.ref);
          setTags(before.tags);
                </option>
              ))}
            </select>
          </label>{' '}
          <button
            type="button"
            data-testid="claim-template-add"
